  "track.kotlin.m.smartcast.s.openProp.rule.explain": "Một class con có thể override name bằng getter trả giá trị khác mỗi lần đọc. Vì vậy dù là val, trình biên dịch không coi hai lần đọc là một.",
  "track.kotlin.m.smartcast.ev.openProp.rule": "property open hoặc có getter tự viết: không",
  "track.kotlin.m.smartcast.s.openProp.use.title": "Lỗi biên dịch ở p.name.uppercase()",
