  "track.kotlin.m.smartcast.ev.openProp.use": "Lỗi biên dịch ở p.name.uppercase()",
  "track.kotlin.m.smartcast.s.openProp.fix.title": "Đọc một lần vào val cục bộ",
  "track.kotlin.m.smartcast.s.openProp.fix.explain": "val name = p.name; if (name != null) name.uppercase(). Đọc một lần thì dù getter trả gì, giá trị đã kiểm chính là giá trị được dùng.",
  "track.kotlin.m.smartcast.ev.openProp.fix": "Đọc một lần vào val cục bộ",
