  "track.kotlin.m.delegate.s.none.start.explain": "Chế độ NONE: không khóa, không compareAndSet. Ai đó chọn nó vì \"nhanh hơn\".",
  "track.kotlin.m.delegate.ev.none.start": "Chọn lazy(NONE) { openDb() }",
