  "track.kotlin.m.delegate.s.none.first.explain": "Cả hai thấy chưa có giá trị và cùng chạy initializer.",
  "track.kotlin.m.delegate.ev.none.first": "A và B cùng chạy openDb()",
  "track.kotlin.m.delegate.s.none.next.title": "Hai luồng có thể nhận hai kết nối khác nhau",
  "track.kotlin.m.delegate.s.none.next.explain": "Mỗi luồng ghi kết quả của mình mà không đồng bộ. A có thể đang dùng kết nối 1 trong khi B và các lần đọc sau dùng kết nối 2; kết nối 1 không ai đóng.",
  "track.kotlin.m.delegate.ev.none.next": "Hai luồng có thể nhận hai kết nối khác nhau",
