  "track.kotlin.m.scope.ev.nestedApply.first": "apply ngoài: title = Booking.title",
  "track.kotlin.m.scope.s.nestedApply.next.title": "apply trong: Patient không có title, nên gán vào Booking.title",
  "track.kotlin.m.scope.s.nestedApply.next.explain": "Trong apply trong, this gần nhất là Patient. Patient không có title, nên trình biên dịch dùng title của receiver bên ngoài, Booking. Lịch hẹn bị đổi tiêu đề thành \"Bà\", không có lỗi nào.",
  "track.kotlin.m.scope.ev.nestedApply.next": "apply trong: Patient không có title, nên gán vào Booking.title",
  "track.kotlin.m.scope.s.nestedApply.end.title": "Sửa: also { p -> … } để tên được ghi rõ",
