  "track.kotlin.m.scope.s.letElvis.start.explain": "Ý định: có token thì làm mới, không có thì đăng xuất.",
  "track.kotlin.m.scope.ev.letElvis.start": "Làm mới token bằng ?.let { } ?: logout()",
